package com.nvv.mediadata.data.model.tmdbimport com.nvv.mediadata.data.utils.LocalDateSerializerimport kotlinx.serialization.SerialNameimport kotlinx.serialization.Serializableimport java.time.LocalDate@Serializabledata class Movie(	@SerialName("adult")	override val adult: Boolean = false,	@SerialName("id")	override val id: Long = -1,	@SerialName("backdrop_path")	override val background: String? = null,	@SerialName("poster_path")	override val poster: String? = null,	@SerialName("original_language")	override val originalLanguage: String = "",	@SerialName("genre_ids")	override val genres: List<Int> = emptyList(),	@SerialName("title")	override val title: String = "",	@SerialName("original_title")	override val originalTitle: String = "",	@SerialName("overview")	override val overview: String = "",	@SerialName("popularity")	override val popularity: Double = 0.0,	@SerialName("release_date")	@Serializable(with = LocalDateSerializer::class)	override val releaseDate: LocalDate? = null,	@SerialName("vote_average")	override val voteAverage: Double = 0.0,	@SerialName("vote_count")	override val voteCount: Int = 0) : Media